(function () {
  var quoteId = String((trg && trg.quote_id) || '');
  if (!quoteId) { throw new Error('quote-expiry: the timer payload carries no quote_id'); }
  return {
    quote_id: quoteId,
    decision_id_hint: String((trg && trg.decision_id) || ''),
    // quote_id is a keyword index field on BOTH decision_config and
    // policy_config, and keyword matching is exact and case-sensitive.
    decision_filter: JSON.stringify({ conditions: [{ field: 'quote_id', keyword: quoteId }] }),
    policy_filter: JSON.stringify({ conditions: [{ field: 'quote_id', keyword: quoteId }] }),
    now: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();

(function () {
  function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
  function dedupe(resp) {
    var rows = (resp && resp.data && resp.data.results) ? resp.data.results : [];
    var seen = {}, out = [];
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!r || !r.id || seen[r.id]) continue;
      seen[r.id] = 1; out.push(r);
    }
    return out;
  }
  var decisions = dedupe(dec);
  var policies = dedupe(pol);

  // A bound quote is never lapsed. Two independent proofs, because either one
  // alone can be stale: a policy record on this quote_id, or a BOUND decision.
  var bound = policies.length > 0;
  for (var b = 0; b < decisions.length; b++) {
    var bd = decisions[b].data || {};
    if (bd.outcome === 'BOUND' || bd.decision_status === 'ISSUED') bound = true;
  }

  // decision_seq is THE ordering key — never submission_version, never
  // decided_at (two publisher-side flows are not one clock).
  var target = null;
  for (var i = 0; i < decisions.length; i++) {
    var d = decisions[i].data || {};
    if (d.decision_status !== 'OPEN') continue;
    if (d.superseded_by) continue;
    if (hint && decisions[i].id !== hint) { /* a hint narrows but never widens */ }
    if (!target) { target = decisions[i]; continue; }
    var a = Number((target.data || {}).decision_seq || 0);
    var c = Number(d.decision_seq || 0);
    if (c > a) { target = decisions[i]; }
    else if (c === a && String(d.decided_at || '') > String((target.data || {}).decided_at || '')) { target = decisions[i]; }
  }
  var td = target ? (target.data || {}) : {};
  var expiry = td.quote_validity_expiry ? new Date(td.quote_validity_expiry) : null;
  var expired = !!(expiry && !isNaN(expiry.getTime()) && Date.now() >= expiry.getTime());

  var reasons = [];
  if (!target) reasons.push('no_open_unsuperseded_decision');
  if (bound) reasons.push('quote_is_bound');
  if (target && !expired) reasons.push('quote_validity_expiry_not_reached');

  var lapseSeq = Number((seq && (seq.value !== undefined ? seq.value : seq.count)) || 0);
  var nowIso = iso(new Date());
  return {
    should_lapse: reasons.length === 0,
    skip_reasons: reasons,
    quote_id: String((trg && trg.quote_id) || ''),
    decision_id: target ? String(target.id) : '',
    submission_id: String(td.submission_id || ''),
    submission_version: String(td.submission_version || ''),
    product_code: String(td.product_code || ''),
    product_version: String(td.product_version || ''),
    distributor_account_id: String(td.distributor_account_id || ''),
    outcome_carried: String(td.outcome || ''),
    quote_validity_expiry: String(td.quote_validity_expiry || ''),
    decisions_seen: decisions.length,
    policies_seen: policies.length,
    lapsed_at: nowIso,
    // The append-only chain: a NEW instance records the lapse, and the
    // predecessor gains the forward pointer. Nothing rewrites a decision's
    // meaning in place.
    lapse_record: {
      quote_id: String((trg && trg.quote_id) || ''),
      submission_id: String(td.submission_id || ''),
      submission_version: String(td.submission_version || ''),
      product_code: String(td.product_code || ''),
      product_version: String(td.product_version || ''),
      distributor_account_id: String(td.distributor_account_id || ''),
      outcome: String(td.outcome || ''),
      decision_status: 'SUPERSEDED',
      origin_flow: 'flow-10',
      decided_by: 'system-quote-expiry',
      decided_at: nowIso,
      decision_seq: lapseSeq,
      quote_validity_expiry: String(td.quote_validity_expiry || ''),
      supersedes_decision_id: target ? String(target.id) : '',
      premium_basis: String(td.premium_basis || ''),
      base_premium: Number(td.base_premium || 0),
      total_payable: Number(td.total_payable || 0),
      underwriter_notes: 'Lapsed by flow 10 quote-expiry: quote_validity_expiry '
        + String(td.quote_validity_expiry || '') + ' passed with no bind.'
    }
  };
})();

(function () {
  var rows = (t && t.data && t.data.results) ? t.data.results
           : ((t && t.results) ? t.results : []);
  // artefact 4: a referral task's folder is the DECISION record id, because
  // flow 11 needs an exact-match handle a task delta can never carry.
  var found = null;
  for (var i = 0; i < rows.length; i++) {
    var x = rows[i];
    var tags = x.tags || [];
    var isReferral = false;
    for (var j = 0; j < tags.length; j++) { if (tags[j] === 'referral') isReferral = true; }
    // Never touch a task a person has already resolved. approved/declined are a
    // person's decision and flow 11's trigger; lapsing one would be a lie.
    if (!isReferral) continue;
    if (x.status === 'approved' || x.status === 'declined' || x.status === 'lapsed') continue;
    found = x; break;
  }
  return {
    task_found: !!found,
    task_id: found ? String(found.id) : '',
    task_status_before: found ? String(found.status || '') : '',
    candidates: rows.length
  };
})();
